<section class="wrap section"><span class="eyebrow">INSTITUTION DIRECTORY</span><h1>Colleges & Universities</h1><p class="muted">Demo institution records. Verify all details before production use.</p><form class="search light"><input name="q" value="<?=h($_GET['q']??'')?>" placeholder="Search by institution or city"><input type="hidden" name="page" value="colleges"><button class="btn btn-primary">Search</button></form><div class="cards"><?php $q=trim($_GET['q']??'');$st=$pdo->prepare("SELECT * FROM colleges WHERE name LIKE ? OR city LIKE ? ORDER BY featured DESC,name");$st->execute(["%$q%","%$q%"]);foreach($st as $c):?><a class="college-card" href="<?=url('college',['id'=>$c['id']])?>"><div class="campus-art"><span><?=h($c['kind'])?></span></div><div class="pad"><h3><?=h($c['name'])?></h3><p><?=h($c['city'])?></p><small><?=h($c['kind'])?> · View details →</small></div></a><?php endforeach;?></div></section>